ko.extenders.setting = function (target, option)
{
	var group = option.group,
		key = option.key;

	target.subscribe(function (value)
	{ /* changes are not saved when 'set'.  you have to call api.settings.save */
		api.settings.get(group, key).then(function (data)
		{
			if (data !== value)
					api.settings.set(group, key, value);
		});
	});

	var value = api.settings.getSynchronous(group, key);

	// console.log(group + ' ' + key + ' ' + value);

	target(value);

	// api.settings.get(group, key).then(function (data)
	// {
	//     target(data);
	// });

	return target;
};


function init_time(api) {
	var current_speed = [1.0];
	var speed_stack = [[]];
	var getViewId = function(view) { return view ? view.id : 0; };

	api.time = {
		control: function (view) { engine.call("time.control", view ? view.id : -1); },
		resume: function (view) { engine.call("time.resume", view ? view.id : -1); },
		set: function (target, view) { engine.call("time.set", target, view ? view.id : -1); },
		skip: function (amount, view) { engine.call("time.skip", amount, view ? view.id : -1); },
		pause: function (view) {
			engine.call("time.pause", view ? view.id : -1);
			current_speed[getViewId(view)] = 0;
		},
		play: function (speed, view) {
			engine.call("time.play", speed, view ? view.id : -1);
			current_speed[getViewId(view)] = speed;
		},
		pushSpeed: function (view) {
			var s = current_speed[getViewId(view)];
			if (s === undefined)
					s = 1.0;
			speed_stack[getViewId(view)].push(s);
		},
		popSpeed: function (view) {
			var speed = speed_stack[getViewId(view)].pop();
			if (speed)
					engine.call("time.play", speed, view ? view.id : -1);
			else
					engine.call("time.pause", view ? view.id : -1);
		},
		frameBack: function (view) { engine.call("time.frameBack", view ? view.id : -1); },
		frameForward: function (view) { engine.call("time.frameForward", view ? view.id : -1); },
	};
};

init_time(window.api);


(function(api) {
	api.twitch = {
		//
		// requestLiveStreamList to get a list of live Planetary Annihilation streams on Twith.tv
		//
		// Will get a promise that will be resolved with an array of:
		//      "channel_url" - The URL of the twitch channel
		//      "preview_url_medium" - The URL of the preview image
		//      "stream_title" - The title of the stream
		//      "channel_display_name" - The display name of the channel
		//      "channel_name" - The name of the channel
		//      "viewer_count" - The number of viewers
		//
		// This is not updated automatically and should be called whenever you wish to refresh the list
		//
		requestLiveStreamList: function () {
			var request = {
					'method':   'GET',
					'dataType': 'json',
					'url':      'https://api.twitch.tv/kraken/streams?game=Planetary+Annihilation',
					'headers': { 'Client-ID': '8l2im97lav4vgewitcxbm70capwinaz' },
			};

			var deferred = $.ajax(request).then(function(d) {
					streams = _.map(d.streams, function(stream) {
						return {
							'channel_url': stream.channel.url,
							'channel_display_name': stream.channel.display_name,
							'channel_name': stream.channel.name,
							'stream_title': stream.channel.status,
							'preview_url_large': stream.preview.large,
							'preview_url_medium': stream.preview.medium,
							'preview_url_small': stream.preview.small,
							'viewer_count': stream.viewers,
						};
					});
					return streams;
			});

			return deferred.promise();
		},

		// Open the twitch page in an external browser. This is probably temporary until we get in situ working
		launchTwitchPage: function (channel_name) { engine.call('twitch.launchTwitchPage', channel_name); },
	};
})(window.api);

