function parse(string) {
	if (_.isObject(string))
		return string;

	var result = '';

	try {
		result = JSON.parse(string)
	} catch (e) {
		console.error('failed to parse json: ' + string);
	}

	return result;
}

function stringfy(object) {
	var result = '';

	try {
		result = JSON.stringify(object)
	} catch (e) {
		console.error('failed to stringify object:');
		console.error(object);
	}

	return result;
}

function loadHtml(src)
{
	var start = Date.now();
	var xmlhttp = new XMLHttpRequest();
	try
	{
		xmlhttp.open("GET", src, false);
		xmlhttp.send();
	}
	catch (err)
	{
		console.error(err);
		console.error("error loading " + src + ' ' + err.message + " after " +  (Date.now() - start)/1000 + " seconds" );
		return;
	}
	console.log( src + ' loaded in ' + (Date.now() - start)/1000 + " seconds" );
	return xmlhttp.responseText;
}

function loadScript(src)
{
	var start = Date.now();
	var xmlhttp = new XMLHttpRequest();
	try
	{
		xmlhttp.open('GET', src, false);
		xmlhttp.send('');
	}
	catch (err)
	{
		console.error(err);
		console.error("error loading " + src + " after " +  (Date.now() - start)/1000 + " seconds");
		return false;
	}
	if (xmlhttp.status > 200 && xmlhttp.status != 304)
	{
		console.error('Failed loading ' + src + ' with ' + xmlhttp.status + " after " +  (Date.now() - start)/1000 + " seconds");
		return false;
	}
	try
	{
		console.log( src + ' loaded in ' + (Date.now() - start)/1000 + " seconds" );
		var se = document.createElement('script');
		se.type = "text/javascript";
		se.text = xmlhttp.responseText;
		document.getElementsByTagName('head')[0].appendChild(se);
	}
	catch (err)
	{
		console.error(err);
		console.error("error loading " + src + " after " +  (Date.now() - start)/1000 + " seconds");
		return false;
	}
	return true;
}

function loadCSS(src) {
	var link = document.createElement('link');
	link.href = src;
	link.type = "text/css";
	link.rel = "stylesheet";
	document.getElementsByTagName("head")[0].appendChild(link);
}

